/**
 * Reading `.git` straight off the disk, with no `git` subprocess: the repository root, its git
 * directory (a linked worktree keeps a `.git` FILE pointing at it), the checked-out branch, a ref.
 * Shared by the hooks that run on every tool call, where a `git` start-up is the whole cost.
 *
 * Generated by Claude Code at the user's request.
 */

'use strict';

const fs = require('fs');
const path = require('path');

/** The directory holding `.git` (a folder, or a file in a worktree) at or above `start`, or null. */
function repoRoot(start) {
  let dir = path.resolve(start);
  for (;;) {
    if (fs.existsSync(path.join(dir, '.git'))) return dir;
    const parent = path.dirname(dir);
    if (parent === dir) return null;
    dir = parent;
  }
}

/** The resolved git directory of the repository at `root` (`.git` itself, or what a worktree's `.git` file names), or null. */
function gitDirOf(root) {
  const dot = path.join(root, '.git');
  try {
    if (fs.statSync(dot).isDirectory()) return dot;
    const pointer = fs.readFileSync(dot, 'utf8').match(/^gitdir:\s*(.+)$/m);
    if (!pointer) return null;
    const resolved = path.resolve(root, pointer[1].trim());
    return fs.existsSync(resolved) ? resolved : null;
  } catch {
    return null;
  }
}

/** Walk up from `start` to the repo root: `{ gitDir, root }`, or null outside a repository. */
function findGitDir(start) {
  const root = repoRoot(start);
  const gitDir = root && gitDirOf(root);
  return gitDir ? { gitDir, root } : null;
}

/** A file under the git directory, trimmed, or null. */
function readRef(gitDir, relative) {
  try {
    return fs.readFileSync(path.join(gitDir, relative), 'utf8').trim();
  } catch {
    return null;
  }
}

/** The checked-out branch, or null when HEAD is detached or unreadable. */
function currentBranch(gitDir) {
  const head = readRef(gitDir, 'HEAD');
  const m = head && head.match(/^ref:\s*refs\/heads\/(.+)$/m);
  return m ? m[1].trim() : null;
}

/**
 * Where refs and config live. A linked worktree keeps only its own HEAD in `.git/worktrees/<name>`; branches,
 * packed-refs, origin/HEAD and `config` are in the common directory that `commondir` points at.
 */
function commonDir(gitDir) {
  try {
    const pointer = fs.readFileSync(path.join(gitDir, 'commondir'), 'utf8').trim();
    return pointer ? path.resolve(gitDir, pointer) : gitDir;
  } catch {
    return gitDir;
  }
}

/**
 * The `url` of remote `name` from the repo's `config`, or null when absent or unreadable. The value as written:
 * `url.<base>.insteadOf`, `include` and an inline `#` comment are not applied, unlike `git remote get-url`.
 */
function remoteUrl(gitDir, name = 'origin') {
  const config = readRef(commonDir(gitDir), 'config');
  if (config === null) return null;
  let inSection = false;
  for (const line of config.split(/\r?\n/)) {
    const section = line.match(/^\s*\[\s*([^\s\]"]+)(?:\s+"((?:[^"\\]|\\.)*)")?\s*\]/);
    if (section) {
      inSection = section[1].toLowerCase() === 'remote' && section[2] === name;
      continue;
    }
    const url = inSection && line.match(/^\s*url\s*=\s*(.*?)\s*$/i);
    if (url) return url[1].replace(/^"(.*)"$/, '$1') || null;
  }
  return null;
}

module.exports = { repoRoot, gitDirOf, findGitDir, readRef, currentBranch, commonDir, remoteUrl };
